function setAuthMode(signIn) { $('#auth-title').textContent = signIn ? 'Sign in to Focusly' : 'Create your local account'; $('#auth-submit').textContent = signIn ? 'Sign in' : 'Create local account'; $('#auth-mode').textContent = signIn ? 'Need a local account? Create one' : 'Already have a local account? Sign in'; $('#auth-password').autocomplete = signIn ? 'current-password' : 'new-password'; $('#auth-error').textContent = ''; $('#auth-form').dataset.signIn = signIn ? 'true' : 'false'; }
